import { ErrorRequestHandler } from 'express';
import { ConflictError, NotFoundError, ValidationError } from '../../../domain/errors/DomainErrors';
import { BadRequestError } from '../RequestReader';

function isJsonParseError(err: unknown): boolean {
  return typeof err === 'object' && err !== null && (err as { type?: unknown }).type === 'entity.parse.failed';
}

function statusFor(err: unknown): number {
  if (err instanceof ValidationError || err instanceof BadRequestError || isJsonParseError(err)) {
    return 400;
  }
  if (err instanceof NotFoundError) {
    return 404;
  }
  if (err instanceof ConflictError) {
    return 409;
  }
  return 500;
}

export const errorHandler: ErrorRequestHandler = (err: unknown, _req, res, _next) => {
  const status = statusFor(err);
  if (status === 500) {
    console.error(err);
    res.status(500).json({ error: 'Internal server error' });
    return;
  }
  const message = err instanceof Error ? err.message : 'Bad request';
  res.status(status).json({ error: message });
};

